SET TIME ZONE 'UTC';
SELECT 1 at;
SELECT TIME WITH TIME ZONE '12:34:56.123456789+03:30:15' AS t,TIMESTAMP WITH TIME ZONE '2000-01-01 12:34:56.123456789-05' AS ts;
SELECT TIME WITH TIME ZONE '12:00:00+03'=TIME WITH TIME ZONE '09:00:00Z' AS t,TIMESTAMP WITH TIME ZONE '2000-01-01 00:00:00+03'=TIMESTAMP WITH TIME ZONE '1999-12-31 21:00:00Z' AS ts;
SELECT TIME WITH TIME ZONE '00:00:00+03'=TIME WITH TIME ZONE '21:00:00Z' AS v;
SELECT TIME WITH TIME ZONE '12:00:00+18:00:01';
SELECT TIME WITH TIME ZONE '12:00:00 Etc/UTC';
SELECT TIMESTAMP WITH TIME ZONE '2000-01-01 12:00:00+02[Europe/Paris]' AS v;
SELECT TIMESTAMP WITH TIME ZONE '-1000000000-01-01 00:00:00-18'<TIMESTAMP WITH TIME ZONE '1000000000-12-31 23:59:59.999999999+18' AS v;
SELECT CAST(TIMESTAMP WITH TIME ZONE '-1000000000-01-01 00:00:00+18' AS TIME(9)) AS t;
SELECT TIMESTAMP WITH TIME ZONE '-1000000000-01-01 00:00:00+18' AT TIME ZONE '-18';
SELECT CAST(TIMESTAMP WITH TIME ZONE '-1000000000-01-01 00:00:00+18' AS DATE);
SELECT DATEADD(timezone_hour,2147483647,TIME WITH TIME ZONE '12:00:00Z');
SELECT TIME WITH TIME ZONE U&'12:00:00\D800';
SET TIME ZONE U&'\D800';
SET TIME ZONE '+03';
SELECT TIME WITH TIME ZONE '12:00:00',TIMESTAMP WITH TIME ZONE '2000-01-01 12:00:00';
SELECT TIME '22:00:00Z',TIMESTAMP '2000-01-01 22:00:00Z';
SELECT CAST(TIMESTAMP WITH TIME ZONE '2000-01-01 22:00:00Z' AS DATE) AS d,CAST(TIMESTAMP WITH TIME ZONE '2000-01-01 22:00:00Z' AS TIME) AS t,CAST(TIMESTAMP WITH TIME ZONE '2000-01-01 22:00:00Z' AS TIMESTAMP) AS ts;
SELECT CAST(DATE '2000-01-01' AS TIMESTAMP WITH TIME ZONE) AS d,CAST(TIME '12:00:00' AS TIME WITH TIME ZONE) AS t,CAST(TIMESTAMP '2000-01-01 12:00:00' AS TIME WITH TIME ZONE) AS ts;
SELECT CAST(TIME WITH TIME ZONE '12:00:00+06' AS TIME) AS v;
SELECT CAST(TIME WITH TIME ZONE '12:00:00Z' AS DATE);
SELECT DATE '2000-01-01'=TIME WITH TIME ZONE '12:00:00Z';
SELECT CAST(TIME WITH TIME ZONE '12:00:00Z' AS TIMESTAMP(9))=CAST(CURRENT_DATE AS TIMESTAMP)+TIME '15:00:00' AS v;
SELECT CAST(TIME WITH TIME ZONE '12:00:00Z' AS TIMESTAMP(9) WITH TIME ZONE)=CAST(CURRENT_DATE AS TIMESTAMP)+TIME '15:00:00' AS v;
SELECT CAST(TIME '12:00:00' AS TIMESTAMP(9) WITH TIME ZONE)=CAST(CURRENT_DATE AS TIMESTAMP)+TIME '12:00:00' AS v;
SELECT TIMESTAMP '2000-01-01 12:00:00' AT TIME ZONE 'UTC';
SELECT TIMESTAMP WITH TIME ZONE '2000-01-01 12:00:00+03' AT TIME ZONE 'UTC';
SELECT TIME WITH TIME ZONE '20:00:00Z' AT TIME ZONE INTERVAL '5:30' HOUR TO MINUTE;
SELECT TIME '12:00:00' AT LOCAL;
SELECT TIMESTAMP WITH TIME ZONE '2000-01-01 12:00:00Z' AT LOCAL;
SELECT TIME '12:00:00' AT TIME ZONE NULL;
SELECT TIME '12:00:00' AT TIME ZONE 'Europe/Paris';
SELECT DATE '2000-01-01' AT LOCAL;
SET TIME ZONE NULL;
SET TIME ZONE INTERVAL '18:00:01' HOUR TO SECOND;
SET TIME ZONE INTERVAL '-3:30:15' HOUR TO SECOND;
SELECT EXTRACT(timezone_hour FROM DATE '2000-01-01') AS h,EXTRACT(timezone_minute FROM TIME '12:00:00') AS m,EXTRACT(timezone_second FROM TIMESTAMP '2000-01-01 12:00:00') AS s;
SELECT EXTRACT(timezone_hour FROM TIME WITH TIME ZONE '12:00:00-03:30:15') AS h,EXTRACT(timezone_minute FROM TIME WITH TIME ZONE '12:00:00-03:30:15') AS m,EXTRACT(timezone_second FROM TIME WITH TIME ZONE '12:00:00-03:30:15') AS s;
SELECT EXTRACT(epoch FROM TIMESTAMP WITH TIME ZONE '2000-01-01 00:00:00+03') AS ts,EXTRACT(epoch FROM TIME WITH TIME ZONE '00:00:00+03') AS t;
SELECT DATEADD(timezone_minute,30,TIME WITH TIME ZONE '12:00:00-03') AS v;
SELECT DATEADD(timezone_second,1,TIMESTAMP WITH TIME ZONE '2000-01-01 12:00:00+18');
SELECT DATEADD(timezone_hour,1,DATE '2000-01-01');
SELECT DATEDIFF(timezone_hour,TIME WITH TIME ZONE '12:00:00-03:30',TIME WITH TIME ZONE '12:00:00+05:30') AS h,DATEDIFF(timezone_minute,TIME WITH TIME ZONE '12:00:00-03:30',TIME WITH TIME ZONE '12:00:00+05:30') AS m;
SELECT DATEADD(month,1,TIMESTAMP WITH TIME ZONE '2000-01-31 12:34:56+03') AS v,DATE_TRUNC(day,TIMESTAMP WITH TIME ZONE '2000-01-01 12:34:56+03') AS d,LAST_DAY(TIMESTAMP WITH TIME ZONE '2000-02-01 12:00:00+03') AS last_day;
SELECT DATE_TRUNC(week_year,TIMESTAMP WITH TIME ZONE '2024-01-01 12:34:56+03') AS v;
SELECT LAST_DAY('2000-01-01 12:00:00+03') AS v;
SELECT TIMESTAMP WITH TIME ZONE '2000-01-01 12:34:56+03'+1 AS v,TIMESTAMP WITH TIME ZONE '2000-01-01 12:00:00+03'+0.5 AS f;
SELECT DATE '2000-01-01'+TIME WITH TIME ZONE '12:34:56+03' AS v,TIME WITH TIME ZONE '12:00:00+03'+TIME '12:00:00' AS t;
SELECT TIMESTAMP '2000-01-01 12:00:00'+TIME WITH TIME ZONE '12:00:00+03' AS v;
SELECT TIMESTAMP WITH TIME ZONE '2000-01-01 12:00:00+03'+TIME '12:00:00' AS v;
SELECT TIME WITH TIME ZONE '12:00:00+03'+TIME WITH TIME ZONE '12:00:00+03';
SELECT TIME WITH TIME ZONE '12:00:00+03'+1;
SELECT TIME WITH TIME ZONE '12:00:00+03'+0.5 AS v;
SELECT TIME WITH TIME ZONE '12:00:00+03'+INTERVAL '1' HOUR AS v;
SELECT TIME WITH TIME ZONE '23:00:00+03'+INTERVAL '1' HOUR;
SELECT TIMESTAMP WITH TIME ZONE '2000-01-01 00:00:00+03'-TIMESTAMP WITH TIME ZONE '1999-12-31 21:00:00Z' AS v;
SELECT TIME WITH TIME ZONE '12:00:00+03'-TIME WITH TIME ZONE '09:00:00Z' AS v;
SELECT TIME WITH TIME ZONE '12:00:00+03'-TIMESTAMP '1970-01-01 12:00:00' AS v;
SELECT CAST(TIMESTAMP WITH TIME ZONE '2000-01-01 23:59:59.999999999+03' AS TIMESTAMP WITH TIME ZONE) AS ts,CAST(TIME WITH TIME ZONE '23:59:59.999999999-05' AS TIME WITH TIME ZONE) AS t;
CREATE TABLE zoned(ts TIMESTAMP(9) WITH TIME ZONE PRIMARY KEY,t TIME(9) WITH TIME ZONE);
INSERT INTO zoned VALUES('2000-01-01 12:00:00Z','12:00:00+03'),('2000-01-02 12:00:00+03','11:00:00Z');
INSERT INTO zoned VALUES('2000-01-01 15:00:00+03',NULL);
SELECT ts,t FROM zoned ORDER BY ts;
SELECT t FROM zoned UNION SELECT TIME WITH TIME ZONE '09:00:00Z';
SELECT MIN(ts) AS lo,MAX(t) AS hi FROM zoned;
SELECT COUNT(*) AS n FROM (VALUES TIME WITH TIME ZONE '12:00:00+03',TIME WITH TIME ZONE '09:00:00Z',TIME WITH TIME ZONE '10:00:00Z',NULL) x(t) GROUP BY t ORDER BY n;
SELECT DISTINCT t FROM (VALUES TIME WITH TIME ZONE '12:00:00+03',TIME WITH TIME ZONE '09:00:00Z',TIME WITH TIME ZONE '10:00:00Z',NULL) x(t);
SELECT COUNT(DISTINCT t) AS n FROM (VALUES TIME WITH TIME ZONE '12:00:00+03',TIME WITH TIME ZONE '09:00:00Z',TIME WITH TIME ZONE '10:00:00Z',NULL) x(t);
SELECT SUM(ts) FROM zoned WHERE FALSE;
SELECT COALESCE(TIME '12:00:00',TIME WITH TIME ZONE '12:00:00+03') AS v;
SELECT ROW(CAST(TIME WITH TIME ZONE '12:00:00Z' AS TIME),1) AS v;
SET TIME ZONE 'Europe/Paris';
SELECT CAST(TIMESTAMP '2024-03-31 02:30:00' AS TIMESTAMP WITH TIME ZONE) AS gap,CAST(TIMESTAMP '2024-10-27 02:30:00' AS TIMESTAMP WITH TIME ZONE) AS overlap;
SELECT TIMESTAMP WITH TIME ZONE '2024-03-31 02:30:00 Europe/Paris' AS gap,TIMESTAMP '2024-03-31 02:30:00 Europe/Paris' AS unzoned;
SELECT TIMESTAMP WITH TIME ZONE '2024-07-01 12:00:00 Europe/Paris' AS summer,TIMESTAMP WITH TIME ZONE '2024-01-01 12:00:00 Europe/Paris' AS winter;
SELECT TIMESTAMP WITH TIME ZONE '2024-07-01 12:00:00+02' AT TIME ZONE 'America/New_York';
SELECT TIMESTAMP WITH TIME ZONE '2400-07-01 12:00:00 Europe/Paris' AS v,TIMESTAMP WITH TIME ZONE '-1000000000-01-01 12:00:00 Europe/Paris' AS lo;
SELECT EXTRACT(timezone_hour FROM DATE '2024-01-01') AS winter,EXTRACT(timezone_hour FROM DATE '2024-07-01') AS summer;
SELECT DATEDIFF(timezone_hour,DATE '2024-01-01',DATE '2024-07-01') AS v;
SELECT CURRENT_TIME(9)=CAST(CURRENT_TIMESTAMP(9) AS TIME(9) WITH TIME ZONE) AS t,LOCALTIME(9)=CAST(CURRENT_TIMESTAMP(9) AS TIME(9)) AS local_time;
CREATE TABLE zone_setting(v VARCHAR);
INSERT INTO zone_setting VALUES('+04:30');
SET TIME ZONE (SELECT v FROM zone_setting);
SELECT EXTRACT(timezone_hour FROM CURRENT_TIMESTAMP) AS h,EXTRACT(timezone_minute FROM CURRENT_TIMESTAMP) AS m;
DROP TABLE zone_setting;
DROP TABLE zoned;
